<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{
 $values=[];foreach(['dhaka','outside'] as $area){$fee=trim((string)($_POST[$area]??''));$estimate=trim((string)($_POST['estimate_'.$area]??''));if($fee!==''&&(!ctype_digit($fee)||(int)$fee>100000))throw new DomainException('Delivery fees must be blank or a whole BDT amount.');if(strlen($estimate)>200)throw new DomainException('Delivery estimates must be under 200 characters.');$values['delivery_'.$area]=$fee===''?null:$fee;$values['delivery_estimate_'.$area]=$estimate;}
 db()->beginTransaction();foreach($values as $name=>$value)query('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$name,$value]);db()->commit();flash('Delivery settings saved. Existing order totals are unchanged.');redirect('admin/settings.php');
}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
render_header('Store settings',true); ?>
<main class="page narrow"><p class="eyebrow">STORE SETTINGS</p><h1>The essentials.</h1><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><form method="post"><?=csrf_input()?><h2>Delivery fees</h2><p>Set your actual delivery charges. Leave blank to confirm the amount with each customer. Enter 0 only if delivery is free.</p><label>Inside Dhaka (BDT)<input type="number" name="dhaka" min="0" max="100000" value="<?=h(setting('delivery_dhaka'))?>"></label><label>Outside Dhaka (BDT)<input type="number" name="outside" min="0" max="100000" value="<?=h(setting('delivery_outside'))?>"></label><label>Inside Dhaka delivery estimate<input name="estimate_dhaka" maxlength="200" value="<?=h(setting('delivery_estimate_dhaka'))?>" placeholder="Enter your actual delivery window"></label><label>Outside Dhaka delivery estimate<input name="estimate_outside" maxlength="200" value="<?=h(setting('delivery_estimate_outside'))?>" placeholder="Enter your actual delivery window"></label><button class="button dark">SAVE SETTINGS ↗</button></form><h2 class="spaced">Google Sheets & email</h2><p>Automatically log new orders and notify urbanwearflawed@gmail.com and customers.</p><a class="button outline" href="<?=url('admin/notifications.php')?>">CONNECT GOOGLE & EMAIL ↗</a><h2 class="spaced">bKash</h2><p>Not connected. The payment adapter is reserved in app/payments.php. Merchant credentials and a tested create/execute/query flow are required before enabling online payment. Never collect PINs or OTPs here.</p></main><?php render_footer(); ?>
